"""Synthetic weather and readings generated by a known model, for fit tests."""

import numpy as np
import pandas as pd

from forecast.physics import Coefficients, simulate


def synthetic_weather(days: int, start="2026-04-01", seed=0) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    index = pd.date_range(start, periods=days * 24, freq="h", tz="UTC")
    hour = index.hour.to_numpy()
    day = np.arange(len(index)) / 24
    air = 12 + 6 * np.sin(2 * np.pi * day / 30) + 4 * np.sin(2 * np.pi * (hour - 9) / 24)
    air = air + rng.normal(0, 1.0, len(index))
    daylight = np.clip(np.sin(np.pi * (hour - 5) / 15), 0, None)
    cloud = np.clip(rng.normal(60, 30, len(index)), 0, 100)
    solar = 700 * daylight * (1 - 0.7 * cloud / 100)
    return pd.DataFrame(
        {"air_temp": air, "shortwave": solar, "cloud_cover": cloud}, index=index
    ).rename_axis("valid_at")


def synthetic_readings(
    weather: pd.DataFrame, truth: Coefficients, t0=11.0, every_hours=24,
    first_hour=7, noise=0.0, seed=1,
) -> pd.DataFrame:
    """Readings sampled from the true trajectory, at first_hour then every N hours."""
    trajectory = simulate(t0, weather, truth)
    times = weather.index.append(weather.index[-1:] + pd.Timedelta(hours=1))
    rng = np.random.default_rng(seed)
    picks = np.arange(first_hour, len(trajectory), every_hours)
    return pd.DataFrame({
        "measured_at": times[picks],
        "temp_c": np.round(trajectory[picks] + rng.normal(0, noise, len(picks)), 2),
    })
